import * as legacy from './legacy-content.js';
import {categories,foods,inputs,bases,articles,topics} from './data.js';
import {routeUrl,filterFoods} from './routes.js';
import {icon} from './icons.js';
export const escapeHTML=legacy.escapeHTML;
export const photo=(name,alt,cls='',eager=false)=>`<img class="${cls}" src="/assets/${name}.png" alt="${alt} · 摄影示意" width="960" height="720" loading="${eager?'eager':'lazy'}" decoding="async">`;
export const link=(href,text,cls='text-link')=>`<a class="${cls}" href="${href}">${text}${icon('arrow')}</a>`;
export function convert(html){return html.replace(/<footer class="footer">[^]*?<\/footer>/g,'').replace(/<header class="page-header">[^]*?<\/header>/g,'').replace(/<div class="breadcrumbs">[^]*?<\/div>/g,'').replace(/href="(#[^"]*)"/g,(_,href)=>`href="${routeUrl(href.replaceAll('&amp;','&'))}"`).replaceAll('src="./assets/','src="/assets/').replaceAll('左侧导航','顶部导航').replace(/<h1>/g,'<h2 class="detail-title">').replaceAll('</h1>','</h2>');}
export const cards=items=>convert(legacy.foodCards(items));
const sectionHead=(title,subtitle,href,label)=>`<div class="section-head"><div><h2>${title}</h2><p>${subtitle}</p></div>${href?link(href,label):''}</div>`;
export function home(){return `
<section class="home-hero">${photo('base','温室、菜地与远山','hero-photo',true)}<div class="hero-shade"></div><div class="hero-copy"><h1>从微生物，到日常食材</h1><p>连接食材、基地与生产记录</p><div class="button-row">${link('/foods/','浏览菌养食材','button primary')}${link('/bases/','查看基地溯源','button outline-light')}</div></div><a class="hero-explore" href="#introduction">向下探索 ${icon('down')}</a></section>
<section class="home-section container" id="introduction"><div class="intro-layout"><div><h2>了解菌养食材</h2><p class="intro-text">介绍微生物技术在种植与养殖中的应用，<br>连接食材、肥料与饲料，以及基地的生产和检测记录。</p>${link('/about/','了解更多')}</div>${photo('hero','篮装蔬菜与田园','intro-photo')}</div><div class="process-links">${[['sprout','微生物技术','/knowledge/microbes/'],['sun','种植与养殖','/bases/'],['leaf','菌养食材','/foods/'],['shield','检测与溯源','/knowledge/standards/']].map(([i,t,u],n)=>`<a href="${u}">${icon(i)}<span>${t}</span>${n<3?icon('arrow','process-arrow'):''}</a>`).join('')}</div></section>
<section class="home-section ruled container" id="foods">${sectionHead('菌养食材','从不同的食材，了解背后的生产过程。','/foods/','查看全部食材')}<div class="category-grid">${categories.map(x=>`<a href="/foods/?category=${x.id}" class="category-item">${photo(x.image,x.name)}<div><h3>${x.name}</h3><span>浏览食材 ${icon('arrow')}</span></div></a>`).join('')}</div></section>
<section class="home-section ruled container" id="inputs">${sectionHead('肥料与饲料','了解投入品，探索种植与养殖的生产过程。')}<div class="inputs-grid">${[['fertilizer','微生物肥料','查看分类、成分、适用对象与使用方法。','/inputs/fertilizer/'],['feed','发酵饲料','了解原料、菌种、适用动物与储存说明。','/inputs/feed/']].map(([i,t,p,u])=>`<article>${photo(i,t)}<div><h3>${t}</h3><p>${p}</p>${link(u,i==='feed'?'了解饲料':'了解肥料')}</div></article>`).join('')}</div></section>
<section class="home-section ruled container" id="bases"><div class="base-feature">${photo('base','种植基地','base-photo')}<div><h2>基地溯源</h2><p class="intro-text">看见食材的生产过程</p><p>生产记录 · 日常管理 · 指标监测</p><div class="button-row">${link('/bases/','查看基地','button primary')}${link('/bases/?view=process','查看生产过程','button secondary')}</div><p class="quiet-note">示意图，不代表实际基地</p></div></div></section>
<section class="home-section ruled container" id="knowledge">${sectionHead('科普知识','从微生物，到生产与检测资料。','/knowledge/','全部文章')}<div class="knowledge-layout">${photo('fertilizer','土壤中的幼苗与根系','knowledge-photo')}<div class="article-rows">${articles.slice(0,3).map(x=>`<a class="article-row" href="/knowledge/${x.id}/"><div><span class="muted-label">${topics.find(t=>t.id===x.topic).name}</span><h3>${x.title}</h3><p>${x.intro}</p></div><span>${icon('arrow')}</span></a>`).join('')}</div></div></section>
<section class="home-section ruled container events-section" id="events">${sectionHead('食材安全事件','按风险类型与年份检索，关注原始信息来源。','/events/','查看事件')}<div class="event-shortcuts">${link('/events/?risk=residue','农药残留','topic-link')}${link('/events/?risk=metal','重金属','topic-link')}${link('/events/','年份索引','topic-link')}</div><p class="quiet-note">事件资料整理中。正式内容将展示发生时间、涉及食材、调查信息与来源。</p></section>`;}
export function renderContent(route){let html;switch(route.page){case 'home':return home();case 'foods':{const found=filterFoods(foods,route.query);html=legacy.foodsView(route).replace('<p id="food-count" class="result-count" role="status"></p>',`<p id="food-count" class="result-count" role="status">共 ${found.length} 项食材</p>`).replace('<div id="food-grid" class="product-grid"></div>',`<div id="food-grid" class="product-grid">${found.length?legacy.foodCards(found):legacy.emptyState('暂无匹配食材','请更换条件或重置筛选。')}</div>`);break;}case 'food':html=legacy.foodView(route.id);break;case 'inputs':html=`<div class="page-shell"><p class="demo-note">产品资料为界面示意，真实成分、价格及质量资料待补充。</p>${legacy.inputCards(route.query.type)}</div>`;break;case 'input':html=legacy.inputView(route.id);break;case 'bases':html=legacy.basesView(route);break;case 'base':html=legacy.baseView(route.id,route);break;case 'articles':html=legacy.articlesView(route);break;case 'article':html=legacy.articleView(route.id);break;case 'events':html=legacy.eventsView(route).replace('<p id="event-count" class="result-count" role="status"></p>','<p id="event-count" class="result-count" role="status">事件资料整理中，暂未收录真实事件。</p>');break;case 'event':html=legacy.eventView(route.id);break;case 'about':html=legacy.aboutView();break;default:html=legacy.missingView();}return convert(html);}
export function validRoute(r){return !(['food','input','base','article'].includes(r.page)&&!({food:foods,input:inputs,base:bases,article:articles})[r.page].some(x=>x.id===r.id))&&!(r.page==='event'&&r.id!=='layout-example')&&r.page!=='not-found';}
